package com.foodie.order;import jakarta.persistence.*;import java.math.BigDecimal;@Entity @Table(name="order_item",uniqueConstraints=@UniqueConstraint(columnNames={"order_id","dish_id"})) class OrderItem{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long orderItemId;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="order_id") CustomerOrder order;@Column(name="dish_id",nullable=false) Long dishId;@Column(nullable=false) String dishName;@Column(nullable=false) int quantity;@Column(nullable=false,precision=10,scale=2) BigDecimal price;}
